            &&& g.instance_id() == instance@.id()
            &&& g.value() == v as int
        }

        invariant on tail with (instance) is (v: u64, g: FifoQueue::tail<T>) {
            &&& g.instance_id() == instance@.id()
            &&& g.value() == v as int
